import {scene,project} from './visual-prototype.js';
import {basicPattern,patternAtTarget,aimAtDistance,decisionScore,decisionFeedback,DEFAULT_COSTS} from './model.js';
import {reachLimit} from './bag.js';
import {unprojectSurface} from './surfaces.js';
import {simulateShot} from './simulation-client.js';
import {decisionStory,retryStory} from './decision-coaching.js';
import {tracerSample,tracerTrajectory,TRACER_COLORS} from './tracers.js';
import {createCarryOutlineCache} from './carry-outline.js';
import {CALM} from './conditions.js';
const $=id=>document.getElementById(id),seed=7142026,ns='http://www.w3.org/2000/svg',outline=createCarryOutlineCache();
let base,aim,chosen=false,busy=false,answer=null,first=null,phase='choose',flightStart=0,calculations=0,timing=0;
function pattern(){return patternAtTarget(aim,base);}
function initialize(){base={...basicPattern($('previewProfile').value,scene),aimMode:'carry',conditions:{...CALM}};const max=Math.min(scene.aimRange[1],reachLimit(base));$('previewCarry').min=Math.min(scene.aimRange[0],max);$('previewCarry').max=max;aim=aimAtDistance({x:0,y:1},Math.max(Number($('previewCarry').min),Math.min(max,130)),base.aimXRange);chosen=false;answer=null;first=null;phase='choose';$('previewStatus').textContent='Choose a target. This preview does not save results.';sync();render();}
function sync(){const carry=Math.round(Math.hypot(aim.x,aim.y));$('previewCarry').value=carry;$('previewCarryOut').textContent=carry+' yd';$('previewCarry').disabled=busy||!!answer;$('previewProfile').disabled=busy||!!answer;$('previewReset').disabled=busy;$('previewCommit').disabled=busy||!chosen||!!answer;$('previewCommit').hidden=!!answer;$('previewCommit').textContent=busy?'Shots in progress…':chosen?'Commit & shoot':'Choose a target first';$('previewRetry').hidden=!answer;$('previewRetry').disabled=busy;$('previewFeedback').hidden=!answer||phase!=='result';$('previewHelp').textContent=answer?'Your target is locked. Switch graphics to compare the same shots, or adjust and compare with your first choice.':'Tap or drag on either course to choose direction. Use Intended carry below for distance. Arrow keys work when the course is focused.';}
function render(){for(const svg of document.querySelectorAll('.scene>svg')){let layer=svg.querySelector('[data-preview-layer]');if(!layer){layer=document.createElementNS(ns,'g');layer.setAttribute('data-preview-layer','');svg.insertBefore(layer,svg.querySelector('.prototype-aim'));}let html='',marker='';if(chosen){const a=project(aim);marker+=`<g data-preview-aim-x="${aim.x}" data-preview-aim-y="${aim.y}" transform="translate(${a.x},${a.y})"><circle r="12" fill="#23493680" stroke="#ffe8a2" stroke-width="2"/><path d="M-20 0h10M10 0h10M0-20v10M0 10v10" stroke="#fff5cb" stroke-width="1.5"/></g>`;}
 if(answer&&phase==='flight'){const elapsed=performance.now()-flightStart;for(const [i,shot]of tracerSample(answer.result.points,36).entries()){const path=tracerTrajectory(shot,aim,pattern()).map((p,j)=>{const a=project(p);return `${j?'L':'M'}${a.x.toFixed(2)} ${a.y.toFixed(2)}`;}).join(' ');html+=`<path class="play-flight" d="${path}" pathLength="100" stroke="${TRACER_COLORS[shot.kind]}" stroke-width="1.7" style="animation-delay:${i*8-elapsed}ms"/>`;}}
 if(answer&&phase==='result'){for(const [comparison,target,p]of [[false,aim,pattern()],[true,answer.comparison.aim,answer.comparison.pattern]]){const points=outline(target,p).map(([x,y])=>{const a=project({x,y});return `${a.x.toFixed(2)},${a.y.toFixed(2)}`;}).join(' ');html+=`<polygon data-preview-core="${comparison?'comparison':'chosen'}" points="${points}" fill="none" stroke="${comparison?'#4d9cca':'#edb34e'}" stroke-width="2" ${comparison?'stroke-dasharray="5 4"':''}/>`;}const best=project(answer.comparison.aim);html+=`<path d="M${best.x} ${best.y-7}l6 7-6 7-6-7Z" fill="#3182b1" stroke="#d3eef8" stroke-width="1.2"/>`;for(const [comparison,r]of [[false,answer.result],[true,answer.comparison.result]]){html+=`<g data-preview-dots="${comparison?'comparison':'chosen'}">`;for(let i=0;i<r.points.length;i+=8){const shot=r.points[i],a=project(shot);html+=`<circle data-world-x="${shot.x}" data-world-y="${shot.y}" data-kind="${shot.kind}" cx="${a.x}" cy="${a.y}" r="${comparison?2:2.5}" fill="${comparison?'none':TRACER_COLORS[shot.kind]}" stroke="${comparison?'#4d9cca':'#284a37'}" stroke-width="${comparison?1.2:.6}" opacity=".8"/>`;}html+='</g>';}}
 layer.innerHTML=html+marker;svg.setAttribute('data-preview-calculations',String(calculations));}}
function targetFromPointer(svg,e){if(busy||answer)return;const ct=svg.getScreenCTM();if(!ct)return;const p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;const q=p.matrixTransform(ct.inverse());if(q.y<=236)return;const world=unprojectSurface(scene,q.x,q.y,scene.elevationM);if(!Number.isFinite(world.x)||!Number.isFinite(world.y)||world.y<=0)return;aim=aimAtDistance(world,Math.hypot(aim.x,aim.y),base.aimXRange);chosen=true;sync();render();}
let drag=null;
for(const svg of document.querySelectorAll('.scene>svg')){svg.setAttribute('tabindex','0');svg.setAttribute('role','group');svg.setAttribute('aria-label','Preview course. Tap or drag to choose direction. Use the carry bar for distance. Left and right arrow keys adjust direction.');svg.addEventListener('pointerdown',e=>{if(e.isPrimary===false||e.button!==undefined&&e.button!==0||busy||answer)return;drag=e.pointerId;targetFromPointer(svg,e);svg.setPointerCapture?.(e.pointerId);});svg.addEventListener('pointermove',e=>{if(drag===e.pointerId)targetFromPointer(svg,e);});for(const name of ['pointerup','pointercancel','lostpointercapture'])svg.addEventListener(name,()=>{drag=null;});svg.addEventListener('keydown',e=>{if(busy||answer||!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const carry=Math.hypot(aim.x,aim.y),x=Math.max(base.aimXRange[0],Math.min(base.aimXRange[1],aim.x+(e.key==='ArrowRight'?2:-2)));aim={x,y:Math.sqrt(Math.max(1,carry*carry-x*x))};chosen=true;sync();render();});}
$('previewCarry').addEventListener('input',()=>{if(busy||answer)return;aim=aimAtDistance(aim,Number($('previewCarry').value),base.aimXRange);chosen=true;sync();render();});$('previewProfile').addEventListener('change',initialize);$('previewReset').addEventListener('click',()=>{if(!busy){initialize();$('previewStatus').textContent='Preview reset. Your saved game has not changed.';}});
$('previewRetry').addEventListener('click',()=>{if(busy||!answer)return;if(!first)first={expected:answer.result.expected,breakdown:{...answer.result.breakdown}};answer=null;phase='choose';chosen=false;$('previewStatus').textContent='Adjust your target, then commit. The same shot sample will be used; your first-choice comparison is kept.';sync();render();});
$('previewCommit').addEventListener('click',async()=>{if(busy||answer||!chosen)return;busy=true;phase='calculating';$('previewStatus').textContent='Calculating 4,000 shots… You can switch graphics while you wait.';sync();try{const start=performance.now();answer=await simulateShot({aim:{...aim},pattern:pattern(),scenario:scene,costs:{...DEFAULT_COSTS},seed});timing=performance.now()-start;calculations++;phase='flight';flightStart=performance.now();render();if(!matchMedia('(prefers-reduced-motion: reduce)').matches)await new Promise(resolve=>setTimeout(resolve,1900));phase='result';const feedback=decisionFeedback(aim,pattern(),answer.result,answer.comparison,scene),score=decisionScore(answer.result.expected,answer.comparison.result.expected,aim,answer.comparison.aim),story=decisionStory(aim,pattern(),answer.result,answer.comparison,scene,feedback);$('previewVerdict').dataset.kind=feedback.kind;$('previewVerdict').textContent=Number.isFinite(answer.comparison.result.expected)?`${score}/100 · ${feedback.label}`:feedback.label;$('previewWhy').textContent=story.why;$('previewHow').textContent=story.principle;$('previewExperiment').textContent=story.experiment;$('previewRetryFeedback').hidden=!first;if(first){const retry=retryStory(first,answer.result);$('previewRetryFeedback').textContent=retry.verdict+' '+retry.reason;}
 const regret=answer.result.expected-answer.comparison.result.expected;$('previewCost').textContent=Number.isFinite(regret)?`${Math.max(0,regret).toFixed(2)} estimated strokes lost per shot · ${(Math.max(0,regret)*100).toFixed(1)} per 100 similar shots.`:'A finite strokes-lost comparison is unavailable.';$('previewOutcomes').textContent=Object.entries(answer.result.counts).filter(([,n])=>n).map(([kind,n])=>`${kind}: ${(n/answer.result.n*100).toFixed(1)}%`).join(' · ');$('previewTiming').textContent=`Calculation: ${(timing/1000).toFixed(2)} s using ${answer.execution||'the shared simulator'}. Switching graphics reuses this result; it does not measure a new calculation.`;$('previewStatus').textContent='4,000 simulated shots · 500 shown · the same outcomes in both graphics. Preview only; nothing saved.';
 }catch(error){answer=null;phase='choose';$('previewStatus').textContent='The calculation could not finish. Your target is still selected; try Commit again.';console.warn('Preview calculation did not finish',error);}finally{busy=false;sync();render();}});
for(const id of ['proposedButton','currentButton','compareButton','zoomButton'])$(id).addEventListener('click',render);
initialize();
